{
  "solutions": [
    {
      "id": "P3",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Trong giới hạn thời gian tối đa 200 s và ngân sách điện tối đa 800 kJ, cho phép chạy một phần chu trình (các giá trị n_A và n_B có thể là số thực). Tính lượng nhiệt tối đa $Q_{\\text{max}}$ (đơn vị kJ) có thể lấy được từ ngăn lạnh.",
      "solution": "Ta cần tối đa hoá $Q = 540\\,n_A + 600\\,n_B$ với các ràng buộc\n$60\\,n_A + 40\\,n_B \\le 200$ (thời gian) và $180\\,n_A + 240\\,n_B \\le 800$ (năng lượng), $n_A,n_B\\ge 0$.\\\nĐỉnh cực biên của miền khả thi cho $Q$ đạt khi cả hai bất phương trình đều bằng nhau:\n\\[\\begin{cases}60\\,n_A + 40\\,n_B = 200\\\\180\\,n_A + 240\\,n_B = 800\\end{cases}\\]\\\nGiải hệ, $n_A = \\frac{20}{9}\\approx 2.22$, $n_B = \\frac{5}{3}\\approx 1.67$.\\\nThay vào biểu thức nhiệt: $Q_{\\text{max}} = 540\\times\\frac{20}{9} + 600\\times\\frac{5}{3}=1200 + 1000 = 2200\\,\\text{kJ}$.\\\nKiểm tra: thời gian $=60\\times\\frac{20}{9}+40\\times\\frac{5}{3}=200\\,\\text{s}$, năng lượng $=180\\times\\frac{20}{9}+240\\times\\frac{5}{3}=780\\,\\text{kJ}\\le800\\,\\text{kJ}$, thỏa mãn cả hai ràng buộc.",
      "claims": []
    },
    {
      "id": "P4",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Trong bối cảnh máy lạnh có hai chế độ A và B, xác định phát biểu nào sau đây **sai** khi cho rằng nếu thời gian hoạt động không vượt quá 200 s thì ngân sách điện 800 kJ cũng tự động được đáp ứng.",
      "solution": "Thời gian và năng lượng là hai bất phương trình độc lập. Có các cặp $(n_A,n_B)$ thỏa thời gian ≤200 s nhưng tiêu thụ điện năng >800 kJ (ví dụ $n_A=0$, $n_B=5$). Do đó khẳng định \"thời gian ≤200 s ⇒ năng lượng ≤800 kJ\" là sai.",
      "claims": [
        {
          "text": "Thời gian tối đa 200 s và ngân sách điện 800 kJ là độc lập; việc đáp ứng thời gian không đảm bảo đáp ứng ngân sách điện.",
          "correct": false,
          "misconception": "không nhận thấy tính độc lập"
        },
        {
          "text": "Ví dụ n_A=0, n_B=5 cho thời gian 200 s nhưng công điện 1200 kJ > 800 kJ, vì vậy thời gian ≤200 s không tự động thỏa mãn ngân sách điện.",
          "correct": false,
          "misconception": "cho rằng ví dụ không hợp lệ"
        },
        {
          "text": "Mọi cách chạy chu trình thỏa thời gian ≤200 s đều tiêu thụ điện năng không vượt quá 800 kJ.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Để đạt nhiệt lượng tối đa 2200 kJ trong thời gian 200 s, cần tiêu thụ điện năng 780 kJ, thấp hơn ngân sách 800 kJ.",
          "correct": false,
          "misconception": "suy diễn sai về mức năng lượng tối đa"
        }
      ]
    },
    {
      "id": "P1",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Xác định liệu có thể đạt được lượng nhiệt tối thiểu 2160 kJ mà không vượt quá thời gian tối đa 200 s và ngân sách điện 800 kJ khi cho phép chạy các phần chu trình (các giá trị $n_A$ và $n_B$ có thể là số thực). Nếu khả thi, chỉ ra tổ hợp $(n_A, n_B)$ liên tục nào cho phép dư thừa điện năng lớn nhất; nếu không khả thi, chỉ ra ràng buộc nào (thời gian hay năng lượng) là rào cản quyết định.",
      "solution": "Ta giải hệ bất phương trình:\n\\[\\begin{cases}540\\,n_A + 600\\,n_B \\ge 2160\\\\60\\,n_A + 40\\,n_B \\le 200\\\\180\\,n_A + 240\\,n_B \\le 800\\\\n_A, n_B \\ge 0\\end{cases}\\]\\\nTừ ràng buộc nhiệt, đặt $540 n_A + 600 n_B = 2160 \\Rightarrow n_B = 3.6 - 0.9 n_A$.\\\nThời gian: $60 n_A + 40 n_B \\le 200 \\Rightarrow n_A \\le 7/3$.\\\nNăng lượng: $180 n_A + 240 n_B \\le 800 \\Rightarrow n_A \\ge 16/9$.\\\nVùng khả thi tồn tại với $16/9 \\le n_A \\le 7/3$. Để dư thừa điện năng lớn nhất, cần giảm tiêu thụ điện năng $E = 180 n_A + 240 n_B = 864 - 36 n_A$, vì vậy chọn $n_A$ lớn nhất: $n_A = 7/3$, $n_B = 3/2$.\\\nKhi đó thời gian = $200\\,\\text{s}$ (đạt giới hạn), năng lượng tiêu thụ = $780\\,\\text{kJ}$, dư thừa $800-780 = 20\\,\\text{kJ}$. Vì ràng buộc thời gian đạt giới hạn, thời gian là rào cản quyết định.",
      "claims": [
        {
          "text": "Có thể đạt yêu cầu; ràng buộc thời gian là yếu tố quyết định; tổ hợp tối ưu là $n_A=\\frac{7}{3}$ chu trình, $n_B=\\frac{3}{2}$ chu trình, dư thừa điện năng 20 kJ.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Có thể đạt yêu cầu; ràng buộc năng lượng là quyết định; tổ hợp tối ưu là $n_A=2$ chu trình, $n_B=2$ chu trình, dư thừa điện năng 0 kJ.",
          "correct": false,
          "misconception": "đánh giá sai ràng buộc quyết định"
        },
        {
          "text": "Không thể đạt yêu cầu vì thời gian giới hạn; không có tổ hợp nào thỏa.",
          "correct": false,
          "misconception": "không nhận thấy vùng khả thi"
        },
        {
          "text": "Có thể đạt yêu cầu; ràng buộc thời gian là quyết định; tổ hợp tối ưu là $n_A=4$ chu trình, $n_B=0$, dư thừa điện năng 80 kJ.",
          "correct": false,
          "misconception": "bỏ qua ràng buộc thời gian"
        }
      ]
    },
    {
      "id": "P2",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Chọn tất cả các phát biểu đúng về mối quan hệ giữa COP, thời gian và ngân sách điện trong việc đạt yêu cầu nhiệt 2160 kJ, khi cho phép chạy các phần chu trình ($n_A$, $n_B$ là số thực). Các phát biểu phải dựa trên việc suy ra ràng buộc quyết định (thời gian hay điện năng) sau khi tối ưu hoá sử dụng chế độ có COP cao hơn.",
      "solution": "Tính toán tối ưu cho thấy:\n- COP_A = $540/180 = 3$ > COP_B = $600/240 = 2.5$, vì vậy chế độ A hiệu quả hơn về điện năng.\n- Điểm tối ưu để giảm tiêu thụ điện năng nhất là $(n_A,n_B) = (7/3, 3/2)$, tại đó thời gian đạt giới hạn 200 s và năng lượng tiêu thụ 780 kJ (dư thừa 20 kJ).\\\nDo đó ràng buộc thời gian là yếu tố quyết định, còn năng lượng vẫn còn dư.\nCác phát biểu đúng phản ánh các kết quả trên.",
      "claims": [
        {
          "text": "Với $\\text{COP}_A = 3 > \\text{COP}_B = 2.5$, chế độ A luôn hiệu quả hơn về điện năng so với chế độ B.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Giải bài toán tối ưu cho thấy ràng buộc thời gian là yếu tố quyết định; điểm tối ưu đạt thời gian 200 s và tiêu thụ điện năng 780 kJ, để lại 20 kJ dư thừa.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Do chế độ B nhanh hơn, bất kỳ giải pháp tối ưu nào sẽ ưu tiên sử dụng chế độ B để giảm thời gian, ngay cả khi điều này làm tăng tiêu thụ điện năng.",
          "correct": false,
          "misconception": "đánh giá sai ưu tiên tốc độ"
        },
        {
          "text": "Nếu chỉ xét ràng buộc thời gian ≤200 s, thì luôn tự động thỏa mãn ngân sách điện ≤800 kJ.",
          "correct": false,
          "misconception": "suy diễn sai về mối quan hệ thời gian‑năng lượng"
        }
      ]
    }
  ]
}
